// Builds the MCP app widgets (MCP-APP-CONTRACT.md section 5): inlines src/mcp-app/widgets/ into one self-contained HTML
// page that holds all nine views, and writes src/mcp-app/widgets.generated.ts (WIDGETS, one entry per view, the page
// kept once as a string). `--check` exits 1 when the generated file is stale.
//   node scripts/build-widgets.mjs [--check]
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { transformSync } from "esbuild";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const src = join(root, "src/mcp-app/widgets");
const out = join(root, "src/mcp-app/widgets.generated.ts");

// the order is the scope order: helpers, bridge, views, then the main file that draws and starts
const JS = ["util.js", "bridge.js", "term.js", "views/search.js", "views/post.js", "views/edit.js", "views/collections.js", "views/links.js", "views/webp.js", "views/upload.js", "views/save.js", "views/terminal.js", "main.js"];
const TITLES = {
    search: "capystore: search",
    post: "capystore: post",
    edit: "capystore: edit timeline",
    collections: "capystore: collections",
    links: "capystore: share links",
    webp: "capystore: webp",
    upload: "capystore: upload",
    save: "capystore: save",
    terminal: "capystore: box terminal",
};

const read = (f) => readFileSync(join(src, f), "utf8");

export function buildBundle() {
    const js = `"use strict";(()=>{\n${JS.map(read).join("\n")}\n})();`;
    const code = transformSync(js, { minify: true, target: "es2020", loader: "js", legalComments: "none" }).code.trim();
    const css = transformSync(read("style.css"), { minify: true, loader: "css" }).code.trim();
    // a "</script>" or "</style>" inside the code would end the tag early
    if (/<\/(script|style)/i.test(code + css)) throw new Error("bundle contains a closing script/style tag");
    return read("shell.html").trim().replace("/*CSS*/", () => css).replace("/*JS*/", () => code.replace(/<!--/g, "<\\!--"));
}

export function buildFile() {
    const html = buildBundle();
    if (!html.includes("__DEFAULT_VIEW__")) throw new Error("shell.html lost its default-view marker");
    const titles = Object.entries(TITLES).map(([v, t]) => `    ["${v}", ${JSON.stringify(t)}],`).join("\n");
    return `// GENERATED by scripts/build-widgets.mjs from src/mcp-app/widgets/. Do not edit: run \`npm run widgets\`.
// The page is one string; each WIDGETS entry is that page with its view as the default (built when read).
import { widgetUri, type View } from "./shapes";
import type { Widget } from "./types";

const PAGE = ${JSON.stringify(html)};

const TITLES: [View, string][] = [
${titles}
];

export const WIDGETS: Widget[] = TITLES.map(([view, title]) => ({
    view,
    uri: widgetUri(view),
    title,
    get html() {
        return PAGE.split("__DEFAULT_VIEW__").join(view);
    },
}));
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
    const next = buildFile();
    if (process.argv.includes("--check")) {
        if (!existsSync(out) || readFileSync(out, "utf8") !== next) {
            console.error("widgets.generated.ts is stale: run `npm run widgets` (node scripts/build-widgets.mjs)");
            process.exit(1);
        }
        console.log("widgets.generated.ts is up to date");
    } else {
        writeFileSync(out, next);
        console.log(`wrote src/mcp-app/widgets.generated.ts (${(Buffer.byteLength(next) / 1024).toFixed(1)} KB)`);
    }
}
